class I18n:

    def __init__(self, lang: str='zh') -> None:
        self._lang = lang if lang in SUPPORTED_LANGS else 'zh'

    @property
    def lang(self) -> str:
        return self._lang

    def set_language(self, lang: str) -> None:
        if lang in SUPPORTED_LANGS:
            self._lang = lang

    def t(self, key: str, **kwargs: Any) -> str:
        table = MESSAGES.get(self._lang) or MESSAGES['zh']
        text = table.get(key) or MESSAGES['zh'].get(key, key)
        if kwargs:
            try:
                return text.format(**kwargs)
            except (KeyError, ValueError):
                return text
        return text

def format_adapter_label(adapter, tr: I18n) -> str:
    ips = ', '.join((x.address for x in adapter.ipv4)) or tr.t('nic_no_ipv4')
    state = tr.t('nic_up') if adapter.is_up else tr.t('nic_down')
    return f'{adapter.name}  [{state}]  {ips}'
